import com.vaadin.flow.component.applayout.AppLayout;
import com.vaadin.flow.component.applayout.DrawerToggle;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.html.UnorderedList;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.component.textfield.TextField;
import com.vaadin.flow.router.Route;

@Route("")
public class MainView extends AppLayout {

    private UnorderedList itemList = new UnorderedList();
    private Span itemCount = new Span("Items: 0");
    private TextField itemField = new TextField("Item");
    private int count = 0;

    public MainView() {
        // Create header with app title
        H2 appTitle = new H2("Item Tracker");
        addToNavbar(appTitle);

        // Create main content
        VerticalLayout content = new VerticalLayout();

        // Add title heading
        H1 heading = new H1("Items");

        // Setup item field
        itemField.setPlaceholder("Enter item");
        itemField.setWidth("300px");

        // Setup buttons
        Button addButton = new Button("Add", event -> handleAddItem());
        Button clearButton = new Button("Clear", event -> handleClearItems());

        // Layout for input controls
        VerticalLayout inputLayout = new VerticalLayout();
        inputLayout.add(itemField, addButton, clearButton);
        inputLayout.setSpacing(false);
        inputLayout.setPadding(false);

        // Add components
        content.add(heading, inputLayout, itemList, itemCount);
        content.setSpacing(false);
        content.setPadding(true);

        setContent(content);
    }

    private void handleAddItem() {
        String value = itemField.getValue().trim();

        if (value.isEmpty()) {
            itemField.setInvalid(true);
            itemField.setErrorMessage("Item cannot be empty");
            return;
        }

        itemField.setInvalid(false);
        ListItem item = new ListItem(value);
        itemList.add(item);
        itemField.clear();
        count++;
        updateCount();
    }

    private void handleClearItems() {
        itemList.removeAll();
        count = 0;
        updateCount();
    }

    private void updateCount() {
        itemCount.setText("Items: " + count);
    }
