+package com.vaadinbench;
+
+import com.vaadin.browserless.BrowserlessTest;
+import com.vaadin.browserless.ViewPackages;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@ViewPackages(classes = {MainView.class})
+public class MakeSureItClicksTest extends BrowserlessTest {
+
+    @BeforeEach
+    void setup() {
+        navigate(MainView.class);
+    }
+
+    @Test
+    void verifyComponentsExist() {
+        // Verify shell header
+        assertTrue($view(H2.class).withText("Item Tracker").exists());
+
+        // Verify view components
+        assertTrue($view(H1.class).withText("Items").exists());
+        assertTrue($view(TextField.class).exists());
+        assertTrue($view(Button.class).withText("Add").exists());
+        assertTrue($view(Button.class).withText("Clear").exists());
+        assertTrue($view(Span.class).withText("Items: 0").exists());
+    }
+
+    @Test
+    void addItemsAndVerifyList() {
+        TextField itemField = $view(TextField.class).first();
+        Button addButton = $view(Button.class).withText("Add").first();
+
+        // Add an item
+        itemField.setValue("Test Item");
+        addButton.click();
+
+        // Verify item was added and count updated
+        assertTrue($view(ListItem.class).withText("Test Item").exists());
+        assertTrue($view(Span.class).withText("Items: 1").exists());
+    }
+
+    @Test
+    void addMultipleItems() {
+        TextField itemField = $view(TextField.class).first();
+        Button addButton = $view(Button.class).withText("Add").first();
+
+        // Add multiple items
+        itemField.setValue("Item 1");
+        addButton.click();
+        itemField.setValue("Item 2");
+        addButton.click();
+        itemField.setValue("Item 1");
+        addButton.click();
+
+        // Verify all items were added
+        assertTrue($view(ListItem.class).withText("Item 1").exists());
+        assertTrue($view(ListItem.class).withText("Item 2").exists());
+        assertTrue($view(Span.class).withText("Items: 3").exists());
+    }
+
+    @Test
+    void clearItems() {
+        TextField itemField = $view(TextField.class).first();
+        Button addButton = $view(Button.class).withText("Add").first();
+        Button clearButton = $view(Button.class).withText("Clear").first();
+
+        // Add items
+        itemField.setValue("Item 1");
+        addButton.click();
+        itemField.setValue("Item 2");
+        addButton.click();
+
+        // Clear items
+        clearButton.click();
+
+        // Verify all items were removed and count reset
+        assertTrue($view(Span.class).withText("Items: 0").exists());
+    }
+
+    @Test
+    void emptyValueShowsError() {
+        TextField itemField = $view(TextField.class).first();
+        Button addButton = $view(Button.class).withText("Add").first();
+
+        // Try to add empty item
+        itemField.setValue("");
+        addButton.click();
+
+        // Verify no items were added and field is invalid
+        assertTrue(itemField.isInvalid());
+        assertTrue($view(Span.class).withText("Items: 0").exists());
+    }
+}
